typedef enum LodePNGColorType {
	LCT_GREY = 0, /*grayscale: 1,2,4,8,16 bit*/
	LCT_RGB = 2, /*RGB: 8,16 bit*/
	LCT_PALETTE = 3, /*palette: 1,2,4,8 bit*/
	LCT_GREY_ALPHA = 4, /*grayscale with alpha: 8,16 bit*/
	LCT_RGBA = 6, /*RGB with alpha: 8,16 bit*/
	/*LCT_MAX_OCTET_VALUE lets the compiler allow this enum to represent any invalid
	byte value from 0 to 255 that could be present in an invalid PNG file header. Do
	not use, compare with or set the name LCT_MAX_OCTET_VALUE, instead either use
	the valid color type names above, or numeric values like 1 or 7 when checking for
	particular disallowed color type byte values, or cast to integer to print it.*/
	LCT_MAX_OCTET_VALUE = 255
} LodePNGColorType;

typedef struct LodePNGDecompressSettings LodePNGDecompressSettings;
struct LodePNGDecompressSettings {
	/* Check LodePNGDecoderSettings for more ignorable errors such as ignore_crc */
	unsigned ignore_adler32; /*if 1, continue and don't give an error message if the Adler32 checksum is corrupted*/
	unsigned ignore_nlen; /*ignore complement of len checksum in uncompressed blocks*/

	/*use custom zlib decoder instead of built in one (default: null)*/
	unsigned(*custom_zlib)(unsigned char**, size_t*,
		const unsigned char*, size_t,
		const LodePNGDecompressSettings*);
	/*use custom deflate decoder instead of built in one (default: null)
	if custom_zlib is not null, custom_inflate is ignored (the zlib format uses deflate)*/
	unsigned(*custom_inflate)(unsigned char**, size_t*,
		const unsigned char*, size_t,
		const LodePNGDecompressSettings*);

	const void* custom_context; /*optional custom settings for custom functions*/
};

typedef struct LodePNGCompressSettings LodePNGCompressSettings;
struct LodePNGCompressSettings /*deflate = compress*/ {
	/*LZ77 related settings*/
	unsigned btype; /*the block type for LZ (0, 1, 2 or 3, see zlib standard). Should be 2 for proper compression.*/
	unsigned use_lz77; /*whether or not to use LZ77. Should be 1 for proper compression.*/
	unsigned windowsize; /*must be a power of two <= 32768. higher compresses more but is slower. Default value: 2048.*/
	unsigned minmatch; /*minimum lz77 length. 3 is normally best, 6 can be better for some PNGs. Default: 0*/
	unsigned nicematch; /*stop searching if >= this length found. Set to 258 for best compression. Default: 128*/
	unsigned lazymatching; /*use lazy matching: better compression but a bit slower. Default: true*/

	/*use custom zlib encoder instead of built in one (default: null)*/
	unsigned(*custom_zlib)(unsigned char**, size_t*,
		const unsigned char*, size_t,
		const LodePNGCompressSettings*);
	/*use custom deflate encoder instead of built in one (default: null)
	if custom_zlib is used, custom_deflate is ignored since only the built in
	zlib function will call custom_deflate*/
	unsigned(*custom_deflate)(unsigned char**, size_t*,
		const unsigned char*, size_t,
		const LodePNGCompressSettings*);

	const void* custom_context; /*optional custom settings for custom functions*/
};

typedef struct LodePNGTime {
	unsigned year;    /*2 bytes used (0-65535)*/
	unsigned month;   /*1-12*/
	unsigned day;     /*1-31*/
	unsigned hour;    /*0-23*/
	unsigned minute;  /*0-59*/
	unsigned second;  /*0-60 (to allow for leap seconds)*/
} LodePNGTime;

typedef struct LodePNGInfo {
	/*header (IHDR), palette (PLTE) and transparency (tRNS) chunks*/
	unsigned compression_method;/*compression method of the original file. Always 0.*/
	unsigned filter_method;     /*filter method of the original file*/
	unsigned interlace_method;  /*interlace method of the original file: 0=none, 1=Adam7*/
	LodePNGColorMode color;     /*color type and bits, palette and transparency of the PNG file*/

#ifdef LODEPNG_COMPILE_ANCILLARY_CHUNKS
  /* ... many ancillary fields documented in the header ... */
	unsigned background_defined;
	unsigned background_r;
	unsigned background_g;
	unsigned background_b;
	size_t text_num;
	char** text_keys;
	char** text_strings;
	size_t itext_num;
	char** itext_keys;
	char** itext_langtags;
	char** itext_transkeys;
	char** itext_strings;
	unsigned time_defined;
	LodePNGTime time;
	unsigned phys_defined;
	unsigned phys_x;
	unsigned phys_y;
	unsigned phys_unit;
	unsigned gama_defined;
	unsigned gama_gamma;
	unsigned chrm_defined;
	unsigned chrm_white_x;
	unsigned chrm_white_y;
	unsigned chrm_red_x;
	unsigned chrm_red_y;
	unsigned chrm_green_x;
	unsigned chrm_green_y;
	unsigned chrm_blue_x;
	unsigned chrm_blue_y;
	unsigned srgb_defined;
	unsigned srgb_intent;
	unsigned iccp_defined;
	char* iccp_name;
	unsigned char* iccp_profile;
	unsigned iccp_profile_size;
	unsigned char* unknown_chunks_data[3];
	size_t unknown_chunks_size[3];
#endif /*LODEPNG_COMPILE_ANCILLARY_CHUNKS*/
} LodePNGInfo;

typedef struct LodePNGDecoderSettings {
	LodePNGDecompressSettings zlibsettings; /*in here is the setting to ignore Adler32 checksums*/

	/* Check LodePNGDecompressSettings for more ignorable errors such as ignore_adler32 */
	unsigned ignore_crc; /*ignore CRC checksums*/
	unsigned ignore_critical; /*ignore unknown critical chunks*/
	unsigned ignore_end; /*ignore issues at end of file if possible (missing IEND chunk, too large chunk, ...)*/

	unsigned color_convert; /*whether to convert the PNG to the color type you want. Default: yes*/

#ifdef LODEPNG_COMPILE_ANCILLARY_CHUNKS
	unsigned read_text_chunks; /*if false but remember_unknown_chunks is true, they're stored in the unknown chunks*/
	/*store all bytes from unknown chunks in the LodePNGInfo (off by default, useful for a png editor)*/
	unsigned remember_unknown_chunks;
#endif /*LODEPNG_COMPILE_ANCILLARY_CHUNKS*/
} LodePNGDecoderSettings;

typedef struct LodePNGColorStats {
	unsigned colored; /*not grayscale*/
	unsigned key; /*image is not opaque and color key is possible instead of full alpha*/
	unsigned short key_r; /*key values, always as 16-bit, in 8-bit case the byte is duplicated, e.g. 65535 means 255*/
	unsigned short key_g;
	unsigned short key_b;
	unsigned alpha; /*image is not opaque and alpha channel or alpha palette required*/
	unsigned numcolors; /*amount of colors, up to 257. Not valid if bits == 16 or allow_palette is disabled.*/
	unsigned char palette[1024]; /*Remembers up to the first 256 RGBA colors, in no particular order, only valid when numcolors is valid*/
	unsigned bits; /*bits per channel (not for palette). 1,2 or 4 for grayscale only. 16 if 16-bit per channel required.*/
	size_t numpixels;

	/*user settings for computing/using the stats*/
	unsigned allow_palette; /*default 1. if 0, disallow choosing palette colortype in auto_choose_color, and don't count numcolors*/
	unsigned allow_greyscale; /*default 1. if 0, choose RGB or RGBA even if the image only has gray colors*/
} LodePNGColorStats;

typedef struct LodePNGEncoderSettings {
	LodePNGCompressSettings zlibsettings; /*settings for the zlib encoder, such as window size, ...*/

	unsigned auto_convert; /*automatically choose output PNG color type. Default: true*/

	unsigned filter_palette_zero;
	LodePNGFilterStrategy filter_strategy;
	const unsigned char* predefined_filters;

	unsigned force_palette;
#ifdef LODEPNG_COMPILE_ANCILLARY_CHUNKS
	unsigned add_id;
	unsigned text_compression;
#endif /*LODEPNG_COMPILE_ANCILLARY_CHUNKS*/
} LodePNGEncoderSettings;

typedef struct LodePNGState {
#ifdef LODEPNG_COMPILE_DECODER
	LodePNGDecoderSettings decoder; /*the decoding settings*/
#endif /*LODEPNG_COMPILE_DECODER*/
#ifdef LODEPNG_COMPILE_ENCODER
	LodePNGEncoderSettings encoder; /*the encoding settings*/
#endif /*LODEPNG_COMPILE_ENCODER*/
	LodePNGColorMode info_raw; /*specifies the format in which you would like to get the raw pixel buffer*/
	LodePNGInfo info_png; /*info of the PNG image obtained after decoding*/
	unsigned error;
} LodePNGState;

namespace lodepng {
