import random
import struct
from typing import List, Tuple

# Generator for valid raw pixel buffers for lodepng_encode_memory fuzz stub
# The stub selects one of: GREY/8, RGB/8, RGBA/8, PALETTE/8 (indexed) and picks w,h in 1..33.
# It then computes need = w*h*bpp and truncates/extends FUZZ_PARAM_STR() to exactly that size.
# Our task: produce interesting but valid raw buffers matching that layout, within 4096 bytes.
# We will encode an internal small header to communicate intended (mode,w,h) to the stub via FUZZ_PARAM_STR.
# Since the stub overrides w,h,mode internally, we must ensure our buffer length is large and varied; however,
# FUZZ_PARAM_STR is resized to need, so only content matters. We'll craft content to exercise encoder paths:
# - Solid colors, gradients, checkerboards
# - For palette mode: indices within 0..255
# - For RGB/RGBA: include opaque, transparent, and varying alpha
# - For GREY: ramps and extremes
# We will choose a pattern family seeded by the input seed and generate enough data for up to 33*33*4 bytes.

MAX_W = 33
MAX_H = 33
# Max bytes needed by stub (RGBA): 33*33*4 = 4356, slightly above 4096. We'll limit to 4096 as required.
# The stub will cap need to 2048 if it grows, but our provided buffer will be resized anyway. We'll generate
# 4096 bytes max to satisfy the requirement; the stub will slice/extend.
MAX_BYTES = 4096

# Pattern helpers

def clamp8(x: int) -> int:
    return max(0, min(255, x))


def make_grey_pixel(v: int) -> bytes:
    return bytes([clamp8(v)])


def make_rgb_pixel(r: int, g: int, b: int) -> bytes:
    return bytes([clamp8(r), clamp8(g), clamp8(b)])


def make_rgba_pixel(r: int, g: int, b: int, a: int) -> bytes:
    return bytes([clamp8(r), clamp8(g), clamp8(b), clamp8(a)])


def pattern_solid(width: int, height: int, bpp: int, color: Tuple[int, ...]) -> bytes:
    pix = bytes([clamp8(c) for c in color])
    return pix * (width * height)


def pattern_checker(width: int, height: int, bpp: int, colors: List[Tuple[int, ...]], tile: int = 4) -> bytes:
    out = bytearray()
    for y in range(height):
        for x in range(width):
            idx = ((x // tile) + (y // tile)) & 1
            out.extend(bytes([clamp8(c) for c in colors[idx]]))
    return bytes(out)


def pattern_gradient(width: int, height: int, mode: str) -> bytes:
    # mode in {grey, rgb, rgba, pal}
    out = bytearray()
    for y in range(height):
        for x in range(width):
            fx = x / max(1, width - 1)
            fy = y / max(1, height - 1)
            if mode == 'grey':
                v = int(255 * (0.5 * fx + 0.5 * fy))
                out.extend(make_grey_pixel(v))
            elif mode == 'rgb':
                r = int(255 * fx)
                g = int(255 * fy)
                b = int(255 * (1 - fx))
                out.extend(make_rgb_pixel(r, g, b))
            elif mode == 'rgba':
                r = int(255 * fx)
                g = int(255 * fy)
                b = int(255 * (1 - fy))
                a = int(255 * (0.25 + 0.75 * (fx * fy)))
                out.extend(make_rgba_pixel(r, g, b, a))
            else:  # pal (indices)
                v = int(255 * ((fx * 0.7 + fy * 0.3)))
                out.append(clamp8(v))
    return bytes(out)


def pattern_edges(width: int, height: int, mode: str) -> bytes:
    # Strong edges/borders, useful for filter heuristics
    out = bytearray()
    for y in range(height):
        for x in range(width):
            edge = (x == 0 or y == 0 or x == width - 1 or y == height - 1)
            if mode == 'grey':
                v = 0 if edge else 255
                out.extend(make_grey_pixel(v))
            elif mode == 'rgb':
                c = (255, 0, 0) if edge else (0, 255, 0)
                out.extend(make_rgb_pixel(*c))
            elif mode == 'rgba':
                c = (0, 0, 255, 255) if edge else (255, 255, 0, 64)
                out.extend(make_rgba_pixel(*c))
            else:
                out.append(0 if edge else 255)
    return bytes(out)


def pattern_alpha_stripes(width: int, height: int) -> bytes:
    out = bytearray()
    for y in range(height):
        for x in range(width):
            a = 255 if ((x // 2) & 1) else 0
            r = (x * 11 + y * 7) & 255
            g = (x * 3 + y * 13) & 255
            b = (x * 17 + y * 5) & 255
            out.extend(make_rgba_pixel(r, g, b, a))
    return bytes(out)


