            band = (x * 256) // max(1, width)
            out.append(band & 0xFF)
    return bytes(out)


def choose_dims(rng: random.Random) -> Tuple[int, int, str, int]:
    # Choose a plausible mode and dimensions that the stub is likely to select.
    # We don't control the stub's choice, but we generate sufficient data for any.
    modes = [('grey', 1), ('rgb', 3), ('rgba', 4), ('pal', 1)]
    mode, chans = rng.choice(modes)
    w = rng.randint(1, MAX_W)
    h = rng.randint(1, MAX_H)
    return w, h, mode, chans


def build_image(w: int, h: int, mode: str, rng: random.Random) -> bytes:
    # Select a pattern family per mode
    if mode == 'grey':
        choice = rng.randrange(4)
        if choice == 0:
            v = rng.choice([0, 64, 128, 192, 255])
            return pattern_solid(w, h, 1, (v,))
        elif choice == 1:
            return pattern_checker(w, h, 1, [(0,), (255,)], tile=rng.choice([1, 2, 4, 8]))
        elif choice == 2:
            return pattern_gradient(w, h, 'grey')
        else:
            return pattern_edges(w, h, 'grey')
    elif mode == 'rgb':
        choice = rng.randrange(4)
        if choice == 0:
            color = tuple(rng.randrange(256) for _ in range(3))
            return pattern_solid(w, h, 3, color)
        elif choice == 1:
            c0 = (255, 0, 0)
            c1 = (0, 0, 255)
            return pattern_checker(w, h, 3, [c0, c1], tile=rng.choice([1, 2, 4, 8]))
        elif choice == 2:
            return pattern_gradient(w, h, 'rgb')
        else:
            return pattern_edges(w, h, 'rgb')
    elif mode == 'rgba':
        choice = rng.randrange(4)
        if choice == 0:
            color = (rng.randrange(256), rng.randrange(256), rng.randrange(256), rng.choice([0, 64, 128, 192, 255]))
            return pattern_solid(w, h, 4, color)
        elif choice == 1:
            return pattern_alpha_stripes(w, h)
        elif choice == 2:
            return pattern_gradient(w, h, 'rgba')
        else:
            return pattern_edges(w, h, 'rgba')
    else:  # pal
        choice = rng.randrange(3)
        if choice == 0:
            return pattern_palette_bands(w, h)
        elif choice == 1:
            return pattern_checker(w, h, 1, [(0,), (255,)], tile=rng.choice([1, 2, 4, 8]))
        else:
            return pattern_gradient(w, h, 'pal')


def pad_or_truncate(data: bytes, size: int) -> bytes:
    if len(data) < size:
        return data + b"\x00" * (size - len(data))
    if len(data) > size:
        return data[:size]
    return data


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose an internal target mode/dims and build an image
    w, h, mode, chans = choose_dims(rng)
    img = build_image(w, h, mode, rng)

    # Assemble a buffer possibly larger than needed by the stub; include several tiles for variability
    # Construct a compound image set: concatenate multiple small images of different modes
    # but cap total size to MAX_BYTES.
    buffers: List[bytes] = [img]

    # Add 1-3 additional pattern blocks of random modes to give the fuzzer alternative contents
    extra_blocks = rng.randint(1, 3)
    for _ in range(extra_blocks):
        w2, h2, mode2, _ = choose_dims(rng)
        buffers.append(build_image(w2, h2, mode2, rng))

    data = b"".join(buffers)
    data = pad_or_truncate(data, min(MAX_BYTES, len(data)))

    # Ensure non-empty
    if not data:
        data = b"\x00"

    return data

import random
import struct
from typing import List, Tuple

# This generator produces valid raw RGB/RGBA pixel buffers suitable for the
# provided LodePNG fuzz stubs. The stubs request a FUZZ_PARAM_STR used as the
# image buffer, while width/height/channels are chosen inside the stub.
# We therefore generate a self-describing buffer that begins with a small header
# indicating a suggested width/height/format and then fills remaining bytes with
# image data patterns that are valid regardless of the stub's chosen need.
# The stubs will resize or pad as needed, so returning at least need bytes is fine;
# returning fewer is also acceptable (the stub pads with zeros). We keep size <=4096.

MAX_TOTAL = 4096

# Some small, interesting dimensions to exercise different memory shapes
CANDIDATE_DIMS: List[Tuple[int,int]] = [
    (1,1), (1,8), (8,1), (2,2), (3,3), (4,4), (7,5), (8,8), (16,3), (3,16),
    (16,16), (17,17), (31,31), (32,1), (1,32), (32,32)
]

# Color ramps and patterns
def gradient_rgb(w: int, h: int) -> bytes:
    # Horizontal gradient in R, vertical in G, checker in B
    data = bytearray()
    for y in range(h):
        for x in range(w):
            r = int(255 * x / max(1, w-1))
            g = int(255 * y / max(1, h-1))
            b = 0xFF if ((x ^ y) & 1) else 0x00
            data += bytes((r, g, b))
    return bytes(data)

def solid_rgb(w: int, h: int, color: Tuple[int,int,int]) -> bytes:
    return bytes(list(color) * (w*h))

def stripes_rgb(w: int, h: int, vertical: bool=True) -> bytes:
    data = bytearray()
    for y in range(h):
        for x in range(w):
            on = (x if vertical else y) // max(1, (w if vertical else h)//8 or 1)
            if on % 2 == 0:
                data += b"\x00\x00\x00"
            else:
                data += b"\xFF\xFF\xFF"
    return bytes(data)

def random_rgb(w: int, h: int, rng: random.Random) -> bytes:
    return bytes(rng.getrandbits(8) for _ in range(w*h*3))

def make_rgb_image(w: int, h: int, rng: random.Random) -> bytes:
    choice = rng.randrange(4)
    if choice == 0:
        return gradient_rgb(w, h)
    elif choice == 1:
        return solid_rgb(w, h, (rng.randrange(256), rng.randrange(256), rng.randrange(256)))
    elif choice == 2:
        return stripes_rgb(w, h, vertical=bool(rng.getrandbits(1)))
    else:
        return random_rgb(w, h, rng)

# Some PNG encoders may branch on alpha if given RGBA. Provide RGBA occasionally.
def rgb_to_rgba(rgb: bytes, alpha_mode: int, rng: random.Random) -> bytes:
    # alpha_mode: 0=opaque, 1=checker, 2=gradient, 3=random
    out = bytearray()
    px = len(rgb)//3
    for i in range(px):
        r = rgb[3*i]
        g = rgb[3*i+1]
        b = rgb[3*i+2]
        if alpha_mode == 0:
            a = 255
        elif alpha_mode == 1:
            a = 255 if (i & 1) else 0
        elif alpha_mode == 2:
            a = int(255 * i / max(1, px-1))
        else:
            a = rng.randrange(256)
        out += bytes((r,g,b,a))
    return bytes(out)

def pick_dims(rng: random.Random) -> Tuple[int,int]:
    if rng.random() < 0.7:
        return rng.choice(CANDIDATE_DIMS)
    # Otherwise pick random in 1..32
    w = rng.randrange(1, 33)
    h = rng.randrange(1, 33)
    return w, h

def cap_size(buf: bytes) -> bytes:
    if len(buf) <= MAX_TOTAL:
        return buf
    return buf[:MAX_TOTAL]

def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Decide whether to target RGB or RGBA biased by stubs (both paths exist)
    use_rgba = rng.random() < 0.5

    w, h = pick_dims(rng)

    # Ensure total bytes under cap; choose content accordingly
    rgb = make_rgb_image(w, h, rng)
    if use_rgba:
        alpha_mode = rng.randrange(4)
        pix = rgb_to_rgba(rgb, alpha_mode, rng)
        channels = 4
    else:
        pix = rgb
        channels = 3

    # Build a small optional header to increase variety for consumers that might parse leading bytes.
    # The fuzz stubs ignore it and take the raw buffer directly, so this header will just become the first pixels.
    # Keep header tiny to not exceed 4096 when combined with pixels. Include a magic and suggested dims/format.
    magic = b"RAWI"  # RAW Image marker (opaque to the stubs)
    hdr = bytearray()
    hdr += magic
    hdr += struct.pack('<B', 1)          # version
    hdr += struct.pack('<H', w)          # suggested width
    hdr += struct.pack('<H', h)          # suggested height
    hdr += struct.pack('<B', channels)   # 3 or 4

    body = pix

    # If the body plus header would exceed cap, drop header (pixels are more important)
    if len(hdr) + len(body) > MAX_TOTAL:
        out = body[:MAX_TOTAL]
    else:
        out = bytes(hdr) + body

    # Occasionally append an extra small palette-like block or text to vary entropy (ignored by stubs)
    if rng.random() < 0.2 and len(out) < MAX_TOTAL - 16:
        tag = b"TXT\x00"
        text_len = rng.randrange(4, 32)
        text = bytes(rng.randrange(32, 127) for _ in range(text_len))
        out += tag + struct.pack('<H', text_len) + text

    return cap_size(out)

import random
import struct

# This generator produces valid raw image buffers compatible with LodePNG color modes
# used by the provided fuzz stubs. It focuses on creating buffers that are internally
# consistent with common combinations of colortype/bitdepth and small bounded sizes.
#
# The fuzzer stubs compute the needed size from (w*h*bpp+7)/8 and then consume exactly
# that many bytes. We therefore generate buffers of interesting patterns matching that
# sizing, including bit-packed GREY/PALETTE at 1/2/4/8 bpp and 8/16-bit per channel
# formats for GREY/GA/RGB/RGBA.

# LodePNG colortype constants
LCT_GREY = 0
LCT_RGB = 2
LCT_PALETTE = 3
LCT_GREY_ALPHA = 4
LCT_RGBA = 6

# Compute bits-per-pixel according to LodePNG rules
# bitdepth is bits per sample; channels depend on color type.
# For palette and grey, bitdepth can be 1,2,4,8; for others typically 8 or 16.

def bpp_for(colortype: int, bitdepth: int) -> int:
    if colortype == LCT_GREY:
        channels = 1
    elif colortype == LCT_RGB:
        channels = 3
    elif colortype == LCT_PALETTE:
        return bitdepth  # indices only
    elif colortype == LCT_GREY_ALPHA:
        channels = 2
    elif colortype == LCT_RGBA:
        channels = 4
    else:
        channels = 4
    return channels * bitdepth

# Pack N pixels of indices for bit depths 1,2,4,8 into bytes
# pattern function returns an index value in range for the bit depth.

def pack_indices(count: int, bitdepth: int, rng: random.Random, pattern: str) -> bytes:
    if bitdepth == 8:
        # One byte per pixel index
        vals = []
        for i in range(count):
            if pattern == "gradient":
                vals.append((i * 37) & 0xFF)
            elif pattern == "checker":
                vals.append(0x00 if (i // 8) % 2 == 0 else 0xFF)
            else:
                vals.append(rng.randrange(0, 256))
        return bytes(vals)
    # For 1/2/4 bpp, bit-pack MSB-first per PNG conventions
    maxv = (1 << bitdepth) - 1
    out = bytearray()
    acc = 0
    bits = 0
    for i in range(count):
        if pattern == "gradient":
            v = (i % (maxv + 1))
        elif pattern == "checker":
            v = 0 if ((i // 8) % 2 == 0) else maxv
        else:
            v = rng.randrange(0, maxv + 1)
        acc = (acc << bitdepth) | (v & maxv)
        bits += bitdepth
        if bits >= 8:
            # emit highest 8 bits
            shift = bits - 8
            byte = (acc >> shift) & 0xFF
            out.append(byte)
            acc &= (1 << shift) - 1 if shift > 0 else 0
            bits = shift
    if bits > 0:
        # pad remaining bits with zeros on the right
        out.append((acc << (8 - bits)) & 0xFF)
    return bytes(out)

# Helpers to generate pixel component values respecting bitdepth and 8/16-bit per channel

def to_bytes_component(value: int, bitdepth: int) -> bytes:
    if bitdepth == 8:
        return bytes([value & 0xFF])
    # 16-bit, big-endian per PNG canonical raw component order where applicable
    v = value & 0xFFFF
    return struct.pack(">H", v)

# Create a buffer for given mode and size with patterned content

def make_buffer(colortype: int, bitdepth: int, w: int, h: int, rng: random.Random) -> bytes:
    pixels = w * h
    if colortype == LCT_PALETTE:
        # Indices only, bit-packed for <8 bitdepth
        pattern = rng.choice(["gradient", "checker", "random"])  # offer varied content
        return pack_indices(pixels, bitdepth, rng, pattern)

    # For non-palette, produce components per pixel
    chans = {LCT_GREY: 1, LCT_GREY_ALPHA: 2, LCT_RGB: 3, LCT_RGBA: 4}.get(colortype, 4)
    out = bytearray()

    # Select a pattern that exercises alpha, gradients, edges
    pattern = rng.choice(["gradient", "checker", "stripes", "random"])

    maxv = (1 << bitdepth) - 1
    for y in range(h):
        for x in range(w):
            i = y * w + x
            comps = []
            if pattern == "gradient":
                # horizontal gradient on color, vertical on alpha if present
                base = (x * maxv) // max(1, w - 1)
                alt = (y * maxv) // max(1, h - 1)
                if colortype in (LCT_GREY, LCT_GREY_ALPHA):
                    g = base
                    comps.append(g)
                    if colortype == LCT_GREY_ALPHA:
                        comps.append(alt)
                else:
                    r = base
                    g = (base * 2 // 3 + alt // 3) % (maxv + 1)
                    b = alt
                    comps.extend([r, g, b])
                    if colortype == LCT_RGBA:
                        comps.append(alt)
            elif pattern == "checker":
                on = ((x // 2) ^ (y // 2)) & 1
                v = maxv if on else 0
                if colortype in (LCT_GREY, LCT_GREY_ALPHA):
                    comps.append(v)
                    if colortype == LCT_GREY_ALPHA:
                        comps.append(maxv if on else maxv // 2)
                else:
                    comps.extend([v, 0, maxv - v])
                    if colortype == LCT_RGBA:
                        comps.append(maxv if on else maxv // 4)
            elif pattern == "stripes":
                v = (x % 4) * (maxv // 3)
                if colortype in (LCT_GREY, LCT_GREY_ALPHA):
                    comps.append(v)
                    if colortype == LCT_GREY_ALPHA:
                        comps.append(maxv if (y % 3 == 0) else maxv // 2)
                else:
                    comps.extend([v, (v * 2) % (maxv + 1), (v * 3) % (maxv + 1)])
                    if colortype == LCT_RGBA:
                        comps.append(maxv if (y % 5 == 0) else maxv // 3)
            else:  # random
                if colortype in (LCT_GREY, LCT_GREY_ALPHA):
                    comps.append(rng.randrange(0, maxv + 1))
                    if colortype == LCT_GREY_ALPHA:
                        comps.append(rng.randrange(0, maxv + 1))
                else:
                    comps.extend([rng.randrange(0, maxv + 1) for _ in range(3)])
                    if colortype == LCT_RGBA:
                        comps.append(rng.randrange(0, maxv + 1))
            for c in comps:
                out += to_bytes_component(c, bitdepth)
    return bytes(out)

# Choose a mode consistent with usage in stubs. The fuzzer varies colortype and bitdepth;
# we will generate a buffer matching a randomly chosen valid combination within the same ranges.

def choose_mode(rng: random.Random):
    # Prefer common conversions: GREY, RGB, RGBA, PALETTE(1/2/4/8), GREY_ALPHA
    ct = rng.choice([LCT_GREY, LCT_RGB, LCT_RGBA, LCT_PALETTE, LCT_GREY_ALPHA])
    if ct == LCT_PALETTE:
        bd = rng.choice([1, 2, 4, 8])
    else:
        bd = 8 if rng.randrange(2) == 0 else 16
    return ct, bd

# Pick small dimensions consistent with stub bounds, emphasizing a spread including edge cases

def choose_dims(rng: random.Random):
    # favor 1xN stripes, squares, and small rectangles
    choices = [
        (1, rng.randint(1, 16)),
        (rng.randint(1, 16), 1),
        (rng.randint(2, 8), rng.randint(2, 8)),
        (rng.randint(9, 16), rng.randint(9, 16)),
        (rng.randint(3, 16), rng.randint(3, 16)),
    ]
    return rng.choice(choices)

# Ensure total size <= 4096 bytes as requested

def cap_dims_to_size(w: int, h: int, bpp: int) -> (int, int):
    need = (w * h * bpp + 7) // 8
    if need <= 4096:
        return w, h
    # Reduce area to fit budget
    # Keep w fixed, reduce h primarily
    max_pixels = (4096 * 8) // max(1, bpp)
    if max_pixels < 1:
        return 1, 1
    if w > max_pixels:
        return max_pixels, 1
    hfit = max(1, max_pixels // w)
    return w, hfit

# Public API

def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    ct, bd = choose_mode(rng)
    w, h = choose_dims(rng)

    bpp = bpp_for(ct, bd)
    w, h = cap_dims_to_size(w, h, bpp)

    buf = make_buffer(ct, bd, w, h, rng)

    # As a final guard, ensure size does not exceed 4096 bytes
    if len(buf) > 4096:
        buf = buf[:4096]

    return buf

import random
from typing import List

# Generate uncompressed payloads (<=256 bytes) that are interesting for DEFLATE.

MAX_LEN = 256

def _rand_bytes(rng: random.Random, n: int) -> bytes:
    return bytes(rng.getrandbits(8) for _ in range(max(0, n)))

def _pattern_repeat(base: bytes, total_len: int) -> bytes:
    if not base or total_len <= 0:
        return b""
    bl = len(base)
    reps, rem = divmod(total_len, bl)
    return base * reps + base[:rem]

def _make_text(rng: random.Random, n: int) -> bytes:
    alpha = b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"
    digits = b"0123456789"
    punct = b" ,.;:\n\t-_/()[]{}"
    pool = alpha + digits + punct
    return bytes(rng.choice(pool) for _ in range(max(0, n)))

def _structured_blocks(rng: random.Random, budget: int) -> bytes:
    chunks: List[bytes] = []
    remaining = max(0, budget)
    while remaining > 0:
        choice = rng.randrange(8)
        # Exponential-like chunk size, clamped to remaining
        clen = int(rng.expovariate(1/32)) if remaining > 0 else 0
        clen = max(1, min(clen, remaining))
        if choice == 0:
            chunks.append(bytes([0]) * clen)
        elif choice == 1:
            chunks.append(bytes([0xFF]) * clen)
        elif choice == 2:
            # Ensure base_len is within [1, min(16, clen)] to avoid empty ranges
            max_base = max(1, min(16, clen))
            base_len = rng.randrange(1, max_base + 1)
            base = bytes((i % 26) + ord('A') for i in range(base_len))
            chunks.append(_pattern_repeat(base, clen))
        elif choice == 3:
            start = rng.randrange(256)
            chunks.append(bytes((start + i) & 0xFF for i in range(clen)))
        elif choice == 4:
            chunks.append(_rand_bytes(rng, clen))
        elif choice == 5:
            chunks.append(_make_text(rng, clen))
        elif choice == 6:
            mlen_max = max(1, min(32, clen))
            mlen = rng.randrange(1, mlen_max + 1)
            motif = _rand_bytes(rng, mlen)
            chunks.append(_pattern_repeat(motif, clen))
        else:
            half = clen // 2
            chunks.append(bytes([0]) * half + _rand_bytes(rng, clen - half))
        remaining -= clen
    return b"".join(chunks)

def _paletted_block(rng: random.Random, n: int, palette_size: int) -> bytes:
    palette_size = max(1, palette_size)
    palette = list({rng.getrandbits(8) for _ in range(palette_size)})
    if not palette:
        palette = [0]
    return bytes(rng.choice(palette) for _ in range(max(0, n)))

def _choose_length(rng: random.Random) -> int:
    interesting = [0,1,2,3,4,5,7,8,15,16,31,32,63,64,127,128,192,255,256]
    if rng.random() < 0.6:
        return min(MAX_LEN, rng.choice(interesting))
    return rng.randrange(0, MAX_LEN + 1)

def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    n = _choose_length(rng)
    if n <= 0:
        return b""

    mode = rng.randrange(10)
    if mode == 0:
        return bytes([0]) * n
    elif mode == 1:
        return bytes([0xFF]) * n
    elif mode == 2:
        return _make_text(rng, n)
    elif mode == 3:
        return _rand_bytes(rng, n)
    elif mode == 4:
        # repeated motif with potential short tail
        mlen_max = max(1, min(64, n))
        mlen = rng.randrange(1, mlen_max + 1)
        motif = _rand_bytes(rng, mlen)
        tail_max = min(mlen, n)
        tail_len = rng.randrange(0, tail_max + 1)
        base = _pattern_repeat(motif, max(0, n - tail_len))
        tail = motif[:tail_len]
        return base + tail
    elif mode == 5:
        palette_size = rng.choice([2,3,4,8])
        return _paletted_block(rng, n, palette_size)
    elif mode == 6:
        return _structured_blocks(rng, n)
    elif mode == 7:
        out = bytearray()
        bit = 0
        while len(out) < n:
            run = min(n - len(out), rng.randrange(1, 33))
            out += bytes([0x00 if bit == 0 else 0x01]) * run
            bit ^= 1
        return bytes(out)
    elif mode == 8:
        up = rng.choice([True, False])
        start = rng.randrange(256)
        if up:
            return bytes((start + i) & 0xFF for i in range(n))
        else:
            return bytes((start - i) & 0xFF for i in range(n))
    else:
        header_len = rng.randrange(0, min(32, n) + 1)
        header = _make_text(rng, header_len)
        body = _structured_blocks(rng, n - header_len)
        return header + body
